-- Import data resmi Bantuan Alsintan Kabupaten Way Kanan TA 2025
-- (sumber: Data_Bantuan_Alsintan_Way_Kanan_TA_2025.xlsx, sheet "Rekap" & "Data
-- Alsintan 2025" -- 270 unit, 6 jenis, tersebar di 16 nilai kecamatan).
--
-- Data test/dummy lama di tabel alsintan dihapus total (sudah dikonfirmasi
-- user bukan data produksi asli), diganti data resmi ini.
--
-- Catatan kualitas data sumber (tidak diubah, sesuai apa adanya di Excel):
--  - 1 unit Traktor Roda 2 (WK25-TR2-018, penerima "Kodim Way Kanan 0427")
--    tercatat kecamatan "Way Kanan" -- bukan salah satu dari 15 kecamatan
--    resmi di master_kecamatan. Unit ini akan tetap muncul di total & filter
--    per-jenis, tapi TIDAK akan match di choropleth per-kecamatan (peta)
--    karena nama kecamatannya tidak ada di GeoJSON batas wilayah.

delete from alsintan;

-- Perbaiki penamaan jenis lama ("Traktor Crawler", dari migration 0012) agar
-- konsisten dengan penamaan resmi dokumen TA 2025 ("Traktor Roda Crawler").
update master_jenis_alsintan set nama_jenis = 'Traktor Roda Crawler' where nama_jenis = 'Traktor Crawler';

-- Jaga-jaga bila salah satu dari 6 jenis berikut belum ada di DB.
select v.nama_jenis, v.kategori::kategori_alsintan
from (values
  ('Traktor Roda 4', 'pra_panen'),
  ('Traktor Roda Crawler', 'pra_panen'),
  ('Traktor Roda 2', 'pra_panen'),
  ('Pompa Air', 'pra_panen'),
  ('Hand Sprayer', 'pra_panen'),
  ('Rice Transplanter', 'pra_panen')
) as v(nama_jenis, kategori)
where not exists (select 1 from master_jenis_alsintan m where m.nama_jenis = v.nama_jenis);

